أَنَا /26 الْحَجَّارُ L62464 /26 ، أَنَا /26 ابْنُ اللَّتِيِّ L22678 /26 ، أَنَا /26 السِّجْزِيُّ L46126 /26 ، أَنَا شَيْخُ الإِسْلامِ /26 الأَنْصَارِيُّ L46374 /26 ، أَنَا /26 عَبْدُ الرَّحْمَنِ بْنُ أَحْمَدَ السَّرْخَسِيُّ L63046 /26 ، /26 وَمُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ بَهْرَامٍ L66363 /26 ، قَالَ : ثَنَا /26 حَامِدُ بْنُ مُحَمَّدٍ L14311 /26 ، ثَنَا /26 مُحَمَّدُ بْنُ صَالِحٍ L29352 /26 ، ثَنا /26 دَاوُدُ بْنُ إِبْرَاهِيمَ L60867 /26 ، قَالَ الأَنْصَارِيُّ : وَثَنَا /26 أَحْمَدُ بْنُ مُحَمَّدٍ الأَبِيوَرْدِيُّ L66364 /26 ، ثَنَا /26 عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ زِيَادٍ L23105 /26 . قَالَ الأَنْصَارِيُّ : وَثَنَا /26 مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ إِسْمَاعِيلَ L25086 /26 ، أَنَا /26 مَنْصُورُ بْنُ الْعَبَّاسِ L53951 /26 ، قَالَ : وَابْنُ زِيَادٍ ، أَنَا /26 عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ شِيرَوَيْهِ L23046 /26 ، ثَنَا /26 إِسْحَاقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ L927 /26 . قَالَ الأَنْصَارِيُّ : وَثَنَا /26 يَحْيَى بْنُ عَمَّارٍ L33806 /26 ، ثَنَا /26 مُحَمَّدُ بْنُ عَدِيٍّ الصَّابُونِيُّ L60358 /26 ، ثَنَا /26 أَبُو ذَرٍّ التِّرْمِذِيُّ L61186 /26 ، حَدَّثَنِي /26 دَاوُدُ بْنُ الْوَسِيمِ L16621 /26 ، ثَنَا /26 كَثِيرٌ L6567 /26 ، يَعْنِي ابْنَ عَبْدِ اللَّهِ ، قَالَ : هُوَ وَمَنْ تَقَدَّمَ ، ثَنَا /26 بَقِيَّةُ بْنُ الْوَلِيدِ L1919 /26 ، حَدَّثَنِي /26 مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الْقُشَيْرِيُّ L7051 /26 ، عَنْ /26 حُمَيْدٍ L2531 /26 ، قَالَ الأَنْصَارِيُّ : وَثَنَا /26 عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدِ بْنِ مُحَمَّدٍ L20950 /26 ، ثَنَا /26 عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدِ بْنِ إِدْرِيسَ L20916 /26 ، ثَنَا /26 ابْنُ نَاجِيَةَ L21886 /26 ، قَالَ الأَنْصَارِيُّ : وَثَنَا /26 لُقْمَانُ بْنُ أَحْمَدَ L27133 /26 ، ثَنَا /26 مُحَمَّدُ بْنُ عَبْدِ اللهِ بْن أَحْمَد L31922 /26 ، ثَنَا /26 سُلَيْمَانُ بْنُ أَحْمَدَ L18570 /26 ، ثَنَا /26 زَكَرِيَّا بْنُ يَحْيَى السَّاجِيُّ L17277 /26 ، قَالَ : هُوَ وَابْنُ نَاجِيَةَ ، ثَنَا /26 هَارُونُ بْنُ مُوسَى الْفَرْوِيُّ L7990 /26 ، ثَنَا /26 أَبُو ضَمْرَةَ L718 /26 ، عَنْ /26 حُمَيْدٍ L2531 /26 ، /27 عَنْ /93 أَنَسٍ L720 /93 ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ : /20 " إِنَّ اللَّهَ عَزَّ وَجَلَّ يَحْجُبُ التَّوْبَةَ عَنْ كُلِّ صَاحِبِ بِدْعَةٍ " /27 . وَالْحَدِيثُ قَدْ ذَكَرَهُ الأَهْوَازِيُّ ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ : " إِنَّ كُلَّ ذَنْبٍ لَهُ تَوْبَةٌ إِلَّا صَاحِبَ بِدْعَةٍ مَا لَهُ تَوْبَةٌ " . رَوَاهُ الطَّبَرَانِيُّ فِي مُعْجَمِهِ الصَغِيرِ مِنْ حَدِيثِ شُرَيْحٍ الْقَاضِي ، عَنْ عُمَرَ مَرْفُوعًا : " يَا عَائِشَةُ , إِنَّ الَّذِينَ فَارَقُوا دِينَهُمْ وَكَانُوا شِيَعًا هُمْ أَصْحَابُ الْبِدَعِ ، وَأَصْحَابُ الأَهْوَاءِ لَيْسَ لَهُمْ تَوْبَةٌ ، أَنَا مِنْهُمْ بَرِيءٌ ، وَهُمْ مِنِّي بُرَآءٌ " . حَدِيثٌ ضَعِيفٌ ، وَذَكَرَهُ ابْنُ الْمُحِبِّ فِي كِتَابِ الصِّفَاتِ . وَالْحَدِيثُ قَدْ ذَكَرَهُ الأَهْوَازِيُّ ، أَنَّ رَجُلا مِنْ بَنِي إِسْرَائِيلَ أَظْهَرَ بِدْعَةً ثُمَّ تَابَ مِنْهَا , فَأَوْحَى اللَّهُ إِلَى نَبِيِّ ذَلِكَ الْوَقْتِ : قُلْ لِفُلانٍ تُبْتَ أَنْتَ مِنْ بِدْعَتِكَ ، فَكَيْفَ بِمَنْ أَضْلَلْتَ ؟ * 
